#include <bits/stdc++.h>
using namespace std;
#define int long long
int getScore(int k1,int k2,int m, const vector<int>& ps){
    int k3 = m-k2;
    int sc=ps[k1]*6;
    sc+=(ps[k1+2*k2]-ps[k1])*4;
    sc+=(ps[k1+2*k2+3*k3]-ps[k1+2*k2])*3; return sc;
}

void solve(){
    int n;
    cin>>n;
    vector<int>a(3*n);
    for(int i=0;i<3*n;i++){
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());
    vector<int>ps(3*n+1,0);
    for(int i=0;i<3*n;i++){
        ps[i+1]=ps[i]+a[i];
    }
    int ans=0;
    for(int k=0;k<=n;k++){
        int m=n-k;
       /* auto getScore=[&](<long long l>){
            int k3 = m-l;
            int sc=ps[k]*6;
            sc+=(ps[k+2*l]-ps[k])*4;
            sc+=(ps[k+2*l+3*k3]-ps[k+2*l])*3; return sc;
        };*/
        int l=0;
        int h=m;
        int bk2=0;
        while(l<=h){
            int mid= l+(h-l)/2;
            if(mid<m && getScore(k,mid+1,m,ps)>=getScore(k,mid,m,ps)){
                bk2=mid+1;
                l=mid+1;
            }else{
                if(l==h){
                    bk2=mid;
                }
                h=mid-1;
            }
        }
        for(int k2=max(0LL,bk2-2);k2<=min(m,bk2+2);k2++){
            int curr=getScore(k,k2,m,ps);
            if(curr>ans){
                ans=curr;
            }
        }

    }
    cout<<ans<<endl;
}
int32_t main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    solve();
	}
	

}
